topicChecks.push(...extraChapters.map(ch=>ch.topics.map(topic=>[
  "Which approach best describes "+topic+"?",
  "It focuses on "+topic.toLowerCase()+" as one part of "+ch.title.toLowerCase()+", with attention to correct C++ usage, edge cases, and design trade-offs"
])));
export const lessons=chapters.flatMap((chapter,ci)=>chapter.topics.map((title,i)=>{
 const id=chapter.id+"-"+String(i+1).padStart(2,"0"),g=guideFor(title,ci),[q,answer]=topicChecks[ci][i];
 const pool=topicChecks[ci].filter((_,j)=>j!==i).map(x=>x[1]);
 const distractors=[pool[(i+1)%pool.length],pool[(i+4)%pool.length],pool[(i+7)%pool.length]];
 const options=[answer,...distractors];
 const shift=(i*3+ci)%4,rotated=options.map((_,j)=>options[(j+shift)%4]);
 const correct=rotated.indexOf(answer);
 const about=title+": "+answer+". "+g.about;
 const how=g.how+" Focus on "+title.toLowerCase()+": write down the rule in your own words, trace one concrete example, and check the relevant standard-library or language guarantees before relying on an assumption.";
 return {id,chapterId:chapter.id,course:chapter.course,level:chapter.course==="Basic Course"?"Beginner":"Advanced",number:i+1,title,minutes:chapter.course==="Basic Course"?12:18,tags:[title,chapter.title],summary:about,sections:[{heading:"The core idea",body:about},{heading:"How to reason about it",body:how},{heading:"Common mistakes to avoid",body:"For "+title.toLowerCase()+", remember: "+answer+". Check this rule with a small compiled example, including a boundary case where relevant. Also pay attention to types, object lifetime, ownership, and error paths."}],code:g.code,tip:g.how,practice:g.task+" Then extend your solution with one additional requirement from this chapter: "+chapter.topics[(i+1)%chapter.topics.length].toLowerCase()+".",quiz:{q,opts:rotated,a:correct,why:"This checks "+title.toLowerCase()+". "+answer+". Re-read the lesson explanation and compile a small example to verify the rule."}};
}));
export const chapterTests=Object.fromEntries(chapters.map(c=>[c.id,lessons.filter(l=>l.chapterId===c.id).filter((_,i)=>i%2===0).map(l=>({lessonId:l.id,question:l.quiz.q,options:l.quiz.opts,answer:l.quiz.a,explanation:l.quiz.why}))]));
